(()=>{window.sdOpenDirector=async()=>{try{const meta=await(await fetch('/api/meta')).json();const r=await fetch('/api/director/window',{method:'POST',headers:{'Content-Type':'application/json','X-ScoreDeck-Key':meta.controlKey,'X-ScoreDeck-Epoch':meta.serverEpoch,'X-ScoreDeck-Control-Epoch':meta.controlEpoch},body:JSON.stringify({action:'open'})});const d=await r.json();if(!r.ok)throw Error(d.error);}catch{window.open('/director-bar.html','scoredeck-director','width=1360,height=220,resizable=yes');}};
const scan=()=>{const bottom=document.querySelector('.app-shell .sidebar-bottom');if(bottom&&!document.querySelector('#sd-director-open')){const b=document.createElement('button');b.id='sd-director-open';b.className='button';b.textContent='▤　导播控制栏';b.style.cssText='width:100%;margin-bottom:12px;font-size:12px';b.onclick=window.sdOpenDirector;bottom.prepend(b);}};new MutationObserver(scan).observe(document.getElementById('root'),{childList:true,subtree:true});scan();})();
